import{_ as e,o as t,c as i,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Amrita Kalam windows","description":"Nakshatra-specific Ghati offsets produce auspicious sub-windows.","frontmatter":{"title":"Amrita Kalam windows","description":"Nakshatra-specific Ghati offsets produce auspicious sub-windows.","editLink":false},"headers":[],"relativePath":"computations/panchangam.amrita-kalam.md","filePath":"_generated/computations/panchangam.amrita-kalam.md","lastUpdated":null}'),n={name:"computations/panchangam.amrita-kalam.md"};function o(s,a,l,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="amrita-kalam-windows" tabindex="-1">Amrita Kalam windows <a class="header-anchor" href="#amrita-kalam-windows" aria-label="Permalink to &quot;Amrita Kalam windows&quot;">​</a></h1><p><code class="computation-route-id">panchangam.amrita-kalam</code></p><p>Nakshatra-specific Ghati offsets produce auspicious sub-windows.</p><h2 id="assurance" tabindex="-1">Assurance <a class="header-anchor" href="#assurance" aria-label="Permalink to &quot;Assurance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Current statement</th></tr></thead><tbody><tr><td>Documented and traceable</td><td>Yes — the canonical record includes the process and a worked example.</td></tr><tr><td>Regression or reproduction checked</td><td>Linked to 1 repository test file(s).</td></tr><tr><td>Independently source-supported</td><td>Partial support only; read the provenance note and limitations before generalizing.</td></tr></tbody></table><h2 id="computation-method" tabindex="-1">Computation method <a class="header-anchor" href="#computation-method" aria-label="Permalink to &quot;Computation method&quot;">​</a></h2><p><strong>Method type:</strong> <code>formula</code></p><p>For the Nakshatra active at sunrise and its successor, place a four-Ghati window at that Nakshatra&#39;s configured Amrita offset and retain it only when its start lies inside the sunrise-to-next-sunrise Panchangam day.</p><h3 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h3><ol><li>Find the complete UTC span of the sunrise Nakshatra and the immediately following Nakshatra using the selected engine&#39;s Moon model.</li><li>Look up the Nakshatra-specific Amrita start offset on a 60-Ghati scale.</li><li>Scale both the offset and four-Ghati duration by the actual Nakshatra span rather than by clock minutes.</li><li>Keep a window only when day_start &lt;= start &lt; next_sunrise.</li></ol><h3 id="formulae" tabindex="-1">Formulae <a class="header-anchor" href="#formulae" aria-label="Permalink to &quot;Formulae&quot;">​</a></h3><h4 id="nakshatra-scaled-window" tabindex="-1">Nakshatra-scaled window <a class="header-anchor" href="#nakshatra-scaled-window" aria-label="Permalink to &quot;Nakshatra-scaled window&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>start = N_start + N_duration * offset[n] / 60</span></span>\n<span class="line"><span>end = start + N_duration * 4 / 60</span></span></code></pre></div><ul><li>N_start: Nakshatra start</li><li>N_duration: actual Nakshatra duration</li><li>offset[n]: maintained Amrita Ghati offset for Nakshatra n</li></ul><h3 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h3><h4 id="hyderabad-2026-06-11-drik-ganita" tabindex="-1">Hyderabad, 2026-06-11, Drik Ganita <a class="header-anchor" href="#hyderabad-2026-06-11-drik-ganita" aria-label="Permalink to &quot;Hyderabad, 2026-06-11, Drik Ganita&quot;">​</a></h4><p><strong>Inputs</strong></p><ul><li>Panchangam day: sunrise 05:41:11 IST to next sunrise 05:41:17 IST</li><li>Sunrise Nakshatra: Revati; successor: Ashvini</li><li>Offsets come from AMRITA_GHATIS</li></ul><p><strong>Calculation</strong></p><ol><li>Construct one four-sixtieths window for each of the two full Nakshatra spans.</li><li>Filter by each computed start against the Panchangam-day bounds.</li></ol><p><strong>Result</strong></p><ul><li>05:59:05.5-07:30:45.166667 IST</li><li>23:49:07.4-01:17:56.2 IST; both starts fall within the Panchangam day</li></ul><h3 id="method-notes" tabindex="-1">Method notes <a class="header-anchor" href="#method-notes" aria-label="Permalink to &quot;Method notes&quot;">​</a></h3><ul><li>The registered umbrella claim does not yet provide a criterion-level locator for the complete Amrita offset table.</li></ul><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p><strong>Owning layer:</strong> <code>engine-core</code><br><strong>Claim kind:</strong> <code>textual-rule</code><br><strong>Time basis:</strong> Four-sixtieths of actual Nakshatra duration at the table offset.</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><ul><li>Nakshatra spans</li><li>Amrita offset table</li><li>day bounds</li></ul><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><ul><li>Amrita Kalam windows</li></ul><h2 id="references-and-evidence" tabindex="-1">References and evidence <a class="header-anchor" href="#references-and-evidence" aria-label="Permalink to &quot;References and evidence&quot;">​</a></h2><p><strong>Evidence classes:</strong> <code>textual</code>, <code>published_panchangam</code><br><strong>Verification states:</strong> <code>partially_verified</code><br></p><p>Representative values are compared; the table&#39;s full locator coverage remains incomplete.</p><h3 id="panchangam-mixed-daily-windows" tabindex="-1"><code>panchangam.mixed_daily_windows</code> <a class="header-anchor" href="#panchangam-mixed-daily-windows" aria-label="Permalink to &quot;`panchangam.mixed_daily_windows`&quot;">​</a></h3><p><strong>Evidence class:</strong> <code>textual</code><br><strong>Verification state:</strong> <code>partially_verified</code><br><strong>Locator:</strong> B. V. Raman, Chapter III, printed p. 8 (Nakshatra Tyajyakala table), and Chapter V section 7, printed pp. 13-14 (Durmuhurta); regional tables remain regression-pinned<br><strong>Last reviewed:</strong> 2026-07-22<br><strong>Scope:</strong> The auspicious, inauspicious and Choghadiya response objects are mixed containers. Raman supports the four-Ghati Nakshatra Tyajyakala concept and his printed Durmuhurta scheme, but the project&#39;s regional weekday tables are not identical to Raman&#39;s table and the remaining Brahma Muhurta, Abhijit, Amrita Kalam, Rahu Kalam, Gulika, Yamagandam and Choghadiya components do not yet have criterion-level textual claims. This state records partial evidence, not umbrella verification.</p><h4 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h4><ul><li><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer"><strong>Muhurtha (Electional Astrology)</strong></a> — B. V. Raman; UBS Publishers&#39; Distributors, 1993, ISBN 9788185674681; authority type: <code>modern_synthesis</code></li><li><a href="https://archive.org/details/muhurta-chintamani-hindi" target="_blank" rel="noreferrer"><strong>Muhurta Chintamani</strong></a> — Rama Daivajna; Undated Sanskrit text with Hindi commentary, Internet Archive identifier muhurta-chintamani-hindi; authority type: <code>primary_text_hindi_commentary</code></li></ul><p>The complete machine-readable source registry is available in <a href="/docs/reference/provenance.json"><code>provenance.json</code></a>. A regression fixture or same-code reproduction is not independent verification.</p><h2 id="reproduce-and-review" tabindex="-1">Reproduce and review <a class="header-anchor" href="#reproduce-and-review" aria-label="Permalink to &quot;Reproduce and review&quot;">​</a></h2><ul><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/tests/test_muhurta_windows.py" target="_blank" rel="noreferrer"><code>tests/test_muhurta_windows.py</code></a></li></ul><p>Run the linked tests, then the complete offline contract:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/verify_project.py</span></span></code></pre></div><h2 id="public-surfaces" tabindex="-1">Public surfaces <a class="header-anchor" href="#public-surfaces" aria-label="Permalink to &quot;Public surfaces&quot;">​</a></h2><ul><li><code>python-library</code></li><li><code>mcp</code></li><li><code>ics</code></li><li><code>website</code></li></ul><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Offsets follow one maintained table and are clipped to the Panchangam day convention.</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><ul><li><strong>owner:</strong> <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/telugu_panchangam/engines/base.py" target="_blank" rel="noreferrer"><code>telugu_panchangam/engines/base.py</code></a> — <code>nakshatra_day_windows</code></li></ul><p>This route is generated from <a href="/docs/reference/computations.json"><code>computations.json</code></a>. Edit the registry and canonical reference prose in the same pull request as a behavior change.</p>',49)])])}const m=e(n,[["render",o]]);export{p as __pageData,m as default};
